const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

// ===== 部品 =====
const icons={chat:'M21 11a9 9 0 0 1-9 9H5l-3 2 1-7a9 9 0 1 1 18-4Z M7 11h.01 M12 11h.01 M17 11h.01',home:'M3 10.5 12 3l9 7.5V21h-6v-7H9v7H3Z',gift:'M3 8h18v4H3z M5 12v9h14v-9 M12 8v13 M12 8C3 8 5 0 9 4l3 4Zm0 0c9 0 7-8 3-4l-3 4Z',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Z M4 21a8 8 0 0 1 16 0',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4l-2 4 M10 21h4',back:'m15 5-7 7 7 7',arrow:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',play:'m9 5 10 7-10 7Z',walk:'M13 4a1.5 1.5 0 1 0 0-3 1.5 1.5 0 0 0 0 3Z M9 22l3-7 2 2v5 M11 10l-3 4 M11 10l-1 5 4 3 M11 10l4 1 2 4 M11 10V7l4-1 2 3',survey:'M6 3h12v18H6z M9 7h6 M9 11h6 M9 15h3',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',info:'M12 11v6 M12 7v1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',list:'M8 5h13 M8 12h13 M8 19h13 M3 5h1 M3 12h1 M3 19h1',close:'m6 6 12 12 M6 18 18 6',calendar:'M3 5h18v16H3z M7 2v6 M17 2v6 M3 10h18',chart:'M4 20V10 M10 20V5 M16 20V13 M22 20V2',settings:'M3 6h18 M3 12h18 M3 18h18 M8 3v6 M16 9v6 M10 15v6',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',bag:'M5 8h14l2 13H3z M8 8V6a4 4 0 0 1 8 0v2',wallet:'M3 7h16a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7Z M3 7V5a1 1 0 0 1 1-1h12v3 M17 14h1',coin:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',question:'M9 9a3 3 0 1 1 4 2.8c-.7.4-1 1-1 1.7V14 M12 17v1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',ticket:'M3 8a2 2 0 0 0 2-2h14a2 2 0 0 0 2 2v3a2 2 0 0 0 0 4v3a2 2 0 0 0-2 2H5a2 2 0 0 0-2-2v-3a2 2 0 0 0 0-4V8Z M9 6v14',cart:'M3 4h2l2.4 11h11.2L21 7H6 M9 20a1 1 0 1 0 0-2 1 1 0 0 0 0 2Zm9 0a1 1 0 1 0 0-2 1 1 0 0 0 0 2Z',phone:'M7 2h10a2 2 0 0 1 2 2v16a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2Z M11 18h2',game:'M6 8h12a4 4 0 0 1 4 4v3a3 3 0 0 1-5.5 1.7L15 15H9l-1.5 1.7A3 3 0 0 1 2 15v-3a4 4 0 0 1 4-4Z M7 12h3 M8.5 10.5v3 M16 11h.01 M18 13h.01',plane:'M2 12l20-8-6 18-3-8-11-2Z',yen:'M7 4l5 8 5-8 M12 12v8 M8 14h8 M8 17h8',external:'M14 4h6v6 M20 4l-9 9 M19 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1h5'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.spark}"/></svg>`;
const coin=(cls='')=>`<i class="coin ${cls}" aria-hidden="true">P</i>`;
const money=(v,cls='',label='円相当')=>`<span class="money ${cls}">${coin()}<b>${yen(v)}</b>${label?`<small>${label}</small>`:''}</span>`;
const rate=(pct,cls='')=>`<span class="money ${cls}">${coin()}<b>${Number(pct).toFixed(1)}%</b><small>還元</small></span>`; // spec: 定率は小数第 1 位
const rewardText=(t,cls='')=>(t.rewardMode==='rate'?rate(t.reward,cls):money(t.reward,cls))+(t.sur?'<small class="max">(最大)</small>':''); // spec: SUR は「(最大)」
const button=(text,action,cls='btn',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const link=(text,to,cls='')=>`<a class="${cls}" href="#${to}">${text}</a>`;
const note='<p class="money-note">※円相当表記はドットマネーへの交換・換金後の概算値です。</p>';
const route=()=>decodeURIComponent(location.hash.slice(1)||'home').split('/');
const logo=(o,cls='')=>`<span class="logo ${cls}" style="background:${o.logo.bg};color:${o.logo.fg}" aria-hidden="true">${o.logo.text}</span>`;
function mascot(cls=''){return `<svg class="mascot ${cls}" viewBox="0 0 120 100" aria-hidden="true"><ellipse cx="60" cy="96" rx="34" ry="4" fill="#0003"/><path d="M22 44c-8-10-8-30 0-34 6-3 14 8 18 20Z" fill="#1FA98B" stroke="#fff" stroke-width="3"/><path d="M98 44c8-10 8-30 0-34-6-3-14 8-18 20Z" fill="#1FA98B" stroke="#fff" stroke-width="3"/><ellipse cx="60" cy="58" rx="40" ry="36" fill="#fff"/><ellipse cx="60" cy="78" rx="18" ry="12" fill="#fff"/><circle cx="46" cy="52" r="4" fill="#1E2A26"/><circle cx="74" cy="52" r="4" fill="#1E2A26"/><ellipse cx="60" cy="64" rx="5" ry="3.5" fill="#1E2A26"/><path d="M52 70q8 7 16 0" fill="none" stroke="#1E2A26" stroke-width="2.4" stroke-linecap="round"/><circle cx="36" cy="66" r="5" fill="#FFC9C0" opacity=".8"/><circle cx="84" cy="66" r="5" fill="#FFC9C0" opacity=".8"/></svg>`;}
const ad=(size,label)=>`<div class="ad ad-${size}" aria-label="広告枠"><span>${label}</span></div>`;
const FAIL='<div class="fetch-fail">情報を取得できませんでした。</div>'; // spec 共通文言
// ヘッダー：spec はホーム・探す共に「合算ポイント」と「マイ案件ボタン」。お知らせはプロト独自
function header(title,back,extra=''){const home=!title;return `<header class="app-header">${home?button(`${coin('big')}<b>${yen(total(state))}</b><small>円相当</small>${state.user.pending?`<em>準備中 ${yen(state.user.pending)}</em>`:''}`,'balance','balance-pill','aria-label="合算ポイントの内訳を見る"'):back!==undefined?link(icon('back')+'<span class="sr-only">戻る</span>',back,'icon-button'):'<span class="icon-button"></span>'}${title?`<h1>${title}</h1>`:'<span class="grow"></span>'}${extra}${button(icon('bell'),'notifications','icon-button','aria-label="お知らせ"')}</header>`;}
// ホームのカテゴリタブ（案件画面設定 home_tabs から生成。並び・表示名・アイコン・表示／非表示は管理画面で入稿）
const HT=()=>homeTabsFor(state).map(t=>[t.key,t.label.replace(/\n/g,''),t]);
function nav(){const [page]=route();const active=['offers','offer','mycases','challenges'].includes(page)?'offers':['high','quick','invite','mypage'].includes(page)?page:'home';return `<nav class="bottom-nav" aria-label="メインナビゲーション">${[['home','home','ホーム'],['offers','search','探す'],['high','chart','高還元'],['quick','clock','すぐできる'],['invite','gift','友達招待'],['mypage','user','マイページ']].map(([to,ico,label])=>`<a href="#${to}" class="${active===to?'active':''}" ${active===to?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></a>`).join('')}</nav>`;}

const sectionHead=(title,to,label='すべて見る',sub='')=>`<div class="section-head"><div>${sub?`<span class="section-sub">${sub}</span>`:''}<h2>${title}</h2></div>${to?link(`${label}${icon('arrow')}`,to,'more-link'):''}</div>`;
const empty=(title,sub,ico='survey')=>`<div class="empty">${icon(ico)}<h3>${title}</h3><p>${sub}</p></div>`;
const displaySurveys=()=>state.scenario==='empty'?[]:availableSurveys(state);
const kindIcon={launch:'phone',steps:'walk',video:'play',survey:'survey',offer:'gift',credit:'wallet'};
const statusLabel={challenging:'挑戦中',judging:'判定中',approved:'承認',rejected:'否認'};
const dateLabel={challenging:'挑戦日',judging:'判定日',approved:'承認日',rejected:'否認日'};

// ===== TOP：デイリーミッション（spec daily-mission-section）=====
function missionCard(){const t=todayTasks(state);
 // spec: 未達成「やってみる」／達成済み「受け取る」／受け取り済み「受取済み」（非活性）
 const action=x=>{if(x.state==='claimed')return `<span class="pill done">${icon('check')}受取済み</span>`;if(x.state==='achieved')return button(`${icon('gift')}受け取る`,'claim-mission','pill lime',`data-id="${x.id}"`);const a={steps:'scroll-walk',video:'video'}[x.kind];return a?button(`${icon('down')}やってみる`,a,'pill dark'):link(`${icon('down')}やってみる`,x.to,'pill dark');};
 const row=x=>`<li class="${x.state}"><span class="m-icon ${x.kind} ${x.state!=='todo'?'lit':''}">${icon(kindIcon[x.kind])}</span><div class="m-text"><b>${esc(x.title)}${x.pr?'<em class="pr">PR</em>':''}${x.extra?'<em class="pr new">新</em>':''}</b><small>${esc(x.sub)}</small></div><div class="m-right"><span class="m-reward ${x.state==='claimed'?'dim':''}">${x.rate?`${coin()}${x.rate.toFixed(1)}%`:`${coin()}${yen(x.reward)}`}</span>${action(x)}</div></li>`;
 // 基本ミッションとクレカタブ閲覧を表示。クリア済みとその他はアコーディオンへ。
 const coreKinds=['launch','steps','video','credit'];const core=t.items.filter(x=>coreKinds.includes(x.kind)&&x.state!=='claimed');const rest=[...t.items.filter(x=>x.state==='claimed'),...t.items.filter(x=>!coreKinds.includes(x.kind)&&x.state!=='claimed')];
 const progress=`<div class="mission-progress"><span>今日の進捗</span><div class="bar" role="progressbar" aria-valuemin="0" aria-valuemax="${t.total}" aria-valuenow="${t.done}"><i style="width:${t.total?t.done/t.total*100:0}%"></i></div><b>${t.done}/${t.total} 完了</b></div>`;
 const coreList=t.complete?`<div class="mission-complete"><div class="stamps-row">${t.items.filter(x=>coreKinds.includes(x.kind)).map(x=>`<span class="m-icon ${x.kind} lit">${icon(kindIcon[x.kind])}</span>`).join('')}</div><b>すべてのミッションをクリアしました</b><small>すべての報酬を獲得しました</small></div>`:core.length?`<ul class="mission-list">${core.map(row).join('')}</ul>`:`<div class="mission-complete small"><b>本日の基本ミッションはすべてクリア</b><small>クリア済みは下のリストで確認できます</small></div>`;
 const more=rest.length?`<details class="mission-more" id="mission-more" ${missionMoreOpen?'open':''}><summary>${icon('down','toggle-icon')}クリア済み・その他のミッション<b>${rest.length}</b>${t.claimable&&rest.some(x=>x.state==='achieved')?`<em class="claim-badge">${icon('gift')}受け取り${rest.filter(x=>x.state==='achieved').length}件</em>`:''}</summary><ul class="mission-list">${rest.map(row).join('')}</ul></details>`:'';
 return `<section class="mission-card"><div class="mission-head"><h2>${icon('calendar')}デイリーミッション</h2><span class="mission-count">${t.done}/${t.total}</span></div><div class="mission-panel">${progress}${coreList}${more}<a class="mission-foot" href="#missions"><span>今日できるお仕事 <b>${t.count}</b>件</span><span>最大 ${money(t.potential,'m-inline')} ${icon('arrow')}</span></a></div></section>`;}

// ===== TOP：最上部バナー（spec Braze home_first 320×100 相当。1 配置 1 枚、配信対象外はトルツメ。タップでディープリンク）=====
function topBannerView(){const b=topBanner(state);if(!b)return '';const o=offers.find(x=>x.id===b.destination);const f=b.to?.startsWith('feature/')?featureById(state,b.to.slice(8)):null;return `<a class="top-banner" href="#${slotLink(b)}" data-slot="${b.id}" aria-label="${esc(b.title)}"><div class="tb-copy"><span class="hero-eyebrow">${f?(f.kind==='single'?'PICK UP':'特集'):'PR'}<em class="pr">PR</em></span><b>${esc(b.title)}</b><small>${esc(b.text)}</small></div><div class="tb-side">${o?logo(o,'tb-logo'):''}<span class="pill lime">${f?'特集を見る':'詳しく見る'}${icon('arrow')}</span></div></a>`;}
// ===== TOP：歩いてためる（spec step-milestone）=====
function walkSection(){const d=day(state);const goal=L(state).stepGoal,max=stepMaxCount(state);const reached=stepMilestones(state),can=stepsClaimable(state);const linked=state.stepLink==='linked';const done=d.stepsClaimed>=max;
 // spec の吹き出し文言（iOS）
 const msg=state.stepLink==='unlinked'?'歩いてポイントをためるために、ヘルスケア連携をしましょう。':state.stepLink==='unavailable'?'この端末では歩数を計測できないため、「歩いてためる」機能をご利用いただけません。':done?`${L(state).stepMax.toLocaleString()}歩達成おめでとうございます！明日も頑張りましょう。`:`${goal.toLocaleString()}歩ごとにポイントを獲得しましょう！`;
 const cta=state.stepLink==='unlinked'?button('確認','walk-link','pill outline'):state.stepLink==='unavailable'||done?'':button(`${coin()}獲得する`,'step-select','pill dark',can?'':'disabled');
 return `<section class="walk-compact ${linked?'':'unlinked'}" id="walk"><div class="walk-row"><span class="m-icon steps">${icon('walk')}</span><div class="walk-text"><b>歩いてためる</b><small>今日の歩数 : <strong>${linked?d.steps.toLocaleString():'-'}</strong>${button(icon('question'),'walk-help','icon-inline','aria-label="歩いてためるのヘルプ"')}</small></div>${cta}</div><div class="walk-track" aria-label="${(d.stepsClaimed*goal).toLocaleString()}歩分まで獲得済み">${Array.from({length:max},(_,i)=>{const n=i+1;const st=!linked?'':n<=d.stepsClaimed?'claimed':n===d.stepsClaimed+1&&n<=reached?'ready':'';return `<div class="ms ${st}"><span>${st==='claimed'?icon('check'):coin()}</span><small>${(n*goal).toLocaleString()}歩</small></div>`;}).join('')}</div><p class="walk-msg ${done?'done':''}">${msg}</p></section>`;}


// ===== TOP：その他の部品 =====
function hero(slot){const t=offerTerms(state,slot.destination);const o=t.offer;return `<a href="#${slotLink(slot)}" class="hero" data-slot="${slot.id}"><div class="hero-copy"><span class="hero-eyebrow">${slot.challengeGoal?'みんなでチャレンジ':'期間限定 BOOST'}<em class="pr">PR</em></span><h2>${esc(slot.title).replace(/\n/g,'<br>')}</h2><p>${esc(slot.text)}</p><div class="hero-price">${slot.challengeGoal?`達成でさらに ${money(slot.bonus,'m-hero')}`:`<del>${yen(o.base)}円</del>${rewardText(t,'m-hero')}`}</div></div><div class="hero-side">${logo(o,'hero-logo')}<span class="hero-date">${slot.end.slice(5).replace('-','/')}まで</span></div></a>`;}
function offerTile(o){const t=offerTerms(state,o.id);return link(`<div class="tile-logo">${logo(o)}${t.slot&&t.rewardMode==='flat'&&t.reward>o.base?'<span class="badge-up">期間限定UP</span>':''}</div><span class="tile-name">${esc(o.name)}</span>${rewardText(t,'m-tile')}`,`offer/${o.id}`,'offer-tile');}
function offerRow(o){const t=offerTerms(state,o.id);return link(`${logo(o,'row-logo')}<div class="row-main"><h3>${esc(o.name)}</h3><span class="chip-tag">${esc(o.tag)}</span></div><div class="row-right"><small>${t.slot?'期間限定':t.sur?'すべて達成で':'最大'}</small>${rewardText(t,'m-row')}</div>`,`offer/${o.id}`,'offer-row');}
function hcard(o){const t=offerTerms(state,o.id);return link(`<div class="hcard-logo">${logo(o)}${t.slot&&t.rewardMode==='flat'&&t.reward>o.base?'<span class="badge-up">期間限定UP</span>':''}</div><b class="hcard-name">${esc(o.name)}</b><p>${esc(o.condition)}</p><div class="hcard-foot">${rewardText(t,'m-hcard')}<span class="tag-lime">${esc(o.cost)}</span></div>`,`offer/${o.id}`,'hcard');}
function pillTicker(){const pills=pillSlots(state);if(!pills.length)return '';return `<div class="pill-ticker" role="region" aria-label="お知らせバナー">${pills.map(x=>`<a class="text-pill" href="#${x.to||'offer/'+x.destination}" data-slot="${x.id}">${esc(x.title)}</a>`).join('')}</div>`;}
function challengeCard(c){const o=offers.find(x=>x.id===c.destination);if(!o)return '';const t=offerTerms(state,o.id);const ach=challengeAchieved(c),d=daysLeft(state,c),pct=Math.min(100,Math.round(c.participants/c.challengeGoal*100));const joined=caseFor(state,o.id)?.challengeId===c.id;return `<a class="ch-card ${ach?'achieved':''}" href="#offer/${o.id}" data-slot="${c.id}"><div class="ch-top">${logo(o)}${joined?'<span class="ch-joined">参加中</span>':''}</div><h3>${esc(o.name)}</h3><span class="ch-normal">通常 ${rewardText(t,'m-hcard')}</span><div class="ch-meter" role="progressbar" aria-valuemin="0" aria-valuemax="${c.challengeGoal}" aria-valuenow="${c.participants}"><i style="width:${pct}%"></i></div><small class="ch-count">${c.participants.toLocaleString()} / ${c.challengeGoal.toLocaleString()}人</small><div class="ch-foot"><span class="ch-days">${ach?'達成！':d<=1?'終了間近':`あと${d}日`}</span><b>達成で<br>+${yen(c.bonus)}<small>円相当</small></b></div></a>`;}
function challengeSection(limit=3,more=true){const list=challengeSlots(state);if(!list.length)return '';return `<section class="section challenge-section"><div class="ch-head">${icon('spark')}<h2>チャレンジボーナス</h2><span class="tag warm">開催中${list.length}件</span>${button('しくみ','challenge-guide','text-link small-link')}</div><p class="section-sub">期間内に参加人数が目標に達すると、参加者全員に通常報酬＋ボーナス。</p><div class="ch-grid">${list.slice(0,limit).map(challengeCard).join('')}</div>${more&&list.length>limit?link(`すべてのチャレンジを見る（${list.length}件）${icon('arrow')}`,'challenges','btn secondary wide'):''}</section>`;}
function surveyCards(items){if(!items.length)return `<div class="survey-empty">${empty('アンケートがありません','アンケートが届くと、こちらに表示されます。')}</div>`;return `<div class="hscroll survey-cards" role="region" aria-label="届いたアンケート">${items.map(q=>`<a class="survey-card ${q.type}" href="#answer/${q.id}"><span class="tag ${q.type==='main'?'warm':''}">${q.label}</span><h3>${esc(q.title)}</h3><div class="survey-meta"><span>${icon('clock')}${q.minutes}分</span><span class="pill outline">回答する ${icon('arrow')}</span></div><div class="survey-foot">${money(surveyReward(state,q),'m-survey')}${q.parent?'<small>事前調査にご協力いただいた方へ</small>':''}</div></a>`).join('')}</div>`;}
// spec video-reward-section：配信可否を満たさないユーザーには表示しない。残り 0 は「再生済み」非活性、「本日分終了 n/m」
function videoSection(){if(!adsAllowed(state))return '';const d=day(state),limit=L(state).videoLimit,remaining=videoRemaining(state);const watched=limit-remaining;return `<section class="section"><div class="section-head"><h2>動画を見てためる</h2></div><div class="video-card"><div class="video-copy"><p>カンタン動画再生は１日${limit}回まで！<br>動画広告を見てポイントを獲得しましょう</p>${button(`${icon('play')}${remaining?'再生する':'再生済み'}`,'video','pill dark',remaining?'':'disabled')}</div>${remaining?button(icon('play'),'video','video-thumb','aria-label="動画を再生する"'):`<span class="video-thumb done">${icon('check')}</span>`}</div><div class="video-foot"><span>${coin()}${yen(L(state).videoReward)} <i>× ${limit}</i></span><div class="stamps" aria-label="${watched}回視聴済み">${Array.from({length:limit},(_,i)=>`<i class="${i<watched?'on':''}"></i>`).join('')}<b>${remaining?'':'本日分終了 '}${watched}/${limit}</b></div></div>${remaining?'':link(`アンケートでもためられます${icon('arrow')}`,'surveys','more-link video-more')}</section>`;}
function shopSection(){const t=offerTerms(state,'shop');const shops=[{name:'くらしのマーケット',rate:t.reward,to:'offer/shop',o:offers.find(o=>o.id==='shop'),up:!!t.slot},{name:'サンプルモール',rate:1.2,to:'offers',logo:{bg:'#FF7043',fg:'#fff',text:'M'}},{name:'ふるさとギフト',rate:2,to:'offers',logo:{bg:'#26A69A',fg:'#fff',text:'ふ'}},{name:'サンプル家電',rate:0.5,to:'offers',logo:{bg:'#5C6BC0',fg:'#fff',text:'家'}}];return `<section class="section">${sectionHead('お得な買い物','offers')}<div class="hscroll">${shops.map(s=>link(`<div class="hcard-logo">${logo(s.o||s)}${s.up?'<span class="badge-up">期間限定UP</span>':''}</div><p class="shop-name">${esc(s.name)}</p><div class="hcard-foot">${rate(s.rate,'m-hcard')}<span class="tag-lime">無料</span></div>`,s.to,'hcard shop')).join('')}</div></section>`;}
function casesStrip(){const list=state.user.cases.filter(c=>['challenging','judging'].includes(c.status));if(!list.length)return '';const c=list[list.length-1];const o=offers.find(x=>x.id===c.offerId);return `<section class="section">${sectionHead('マイ案件','mycases','マイ案件へ',`${list.length}件が${c.status==='challenging'?'挑戦中':'判定中'}`)}<a class="case-strip" href="#mycases">${logo(o,'row-logo')}<div class="row-main"><span class="tag ${c.status==='approved'?'':'warm'}">${statusLabel[c.status]}</span><h3>${esc(c.name)}</h3>${o.sur?`<div class="mini-track">${o.sur.map((st,i)=>`<i class="${c.paidStages>i?'on':''}">${i+1}</i>`).join('')}<small>${c.paidStages<o.sur.length?'次は'+o.sur[c.paidStages].label:'すべて達成'}</small></div>`:`<small>${esc(c.condition)}</small>`}</div><div class="row-right"><small>${c.rewardMode==='rate'?'購入額に応じて':'報酬'}</small>${c.rewardMode==='rate'?rate(c.reward,'m-row'):money(c.reward,'m-row')}</div></a></section>`;}
function categoryBanner(title,lead,ico,to,secondary=false){return link(`<div class="tb-copy"><span class="hero-eyebrow">${secondary?'MORE CHANCES':'PICK UP'} <em class="pr">PR</em></span><b>${title}</b><small>${lead}</small></div><div class="tb-side">${icon(ico)}<span class="pill lime">チェック ${icon('arrow')}</span></div>`,to,'top-banner category-banner '+(secondary?'secondary-banner':''));}
const tabArt={daily:['calendar','デイリー<br>ミッション'],steps:['walk','歩数'],challenge:['spark','チャレンジ<br>ボーナス'],game:['game','ゲーム'],shopping:['cart','買い物'],survey:['survey','アンケート'],chat:['chat','チャット'],credit:['wallet','クレカ']};
// カテゴリ広告：運用枠（kind=ad, placements=category）から取得。配信対象外はトルツメ
function campaignBanner(key){const bottom=key.endsWith('-bottom');const tab=bottom?key.slice(0,-7):key;const c=categoryAd(state,tab,bottom?'bottom':'top');if(!c)return '';return `<a class="campaign-ad campaign-${key}" href="#${slotLink(c)}" data-slot="${c.id}" aria-label="${esc(c.brand||c.name)}のキャンペーンを見る"><span class="campaign-label">PR・架空の広告</span><div class="campaign-copy"><span class="campaign-eyebrow">${esc(c.eyebrow||'')}</span><h2>${esc(c.title).replace(/\n/g,'<br>')}</h2><p>${esc(c.text||'')}</p><span class="campaign-cta">詳しく見る ${icon('arrow')}</span></div><div class="campaign-art" aria-hidden="true"><span class="campaign-stamp">${esc(c.stamp||'PR')}</span><div class="campaign-object">${icon(c.icon||'gift')}<b>${esc(c.art||'')}</b></div><i class="deco one">✦</i><i class="deco two">✧</i></div><span class="campaign-brand">${esc(c.brand||'')}</span></a>`;}
function categoryContent(key){if(key==='challenge')return `${categoryBanner('みんなで達成、ボーナス獲得','参加して、いつもの報酬にプラス。','spark','challenges')}${challengeSection(Infinity,false)}${note}`;const category={game:'ゲーム',shopping:'買い物',credit:'金融'}[key];const list=visibleOffers(state).filter(o=>key==='credit'?(o.id==='card'||o.creditCard):o.category===category);return `${campaignBanner(key)}<section class="section">${sectionHead('おすすめの案件','offers/'+category,'もっと見る')}<div class="ocard-grid">${list.map(offerCard).join('')}</div>${!list.length?empty('現在、表示できる案件はありません','案件が追加されるまでお待ちください。','gift'):''}</section>${campaignBanner(key+'-bottom')}${note}`;}
function home(){const key=HT().some(([k])=>k===route()[1])?route()[1]:'daily';if(key==='credit'&&!day(state).creditTabVisited){visitHomeTab(state,key);save();}const tabs=`<nav class="home-tabs" role="tablist" aria-label="ホームのカテゴリ" style="grid-template-columns:repeat(${HT().length},minmax(0,1fr))">${HT().map(([k,label,g])=>`<button role="tab" id="tab-${k}" aria-label="${esc(label)}" aria-controls="home-panel" aria-selected="${key===k}" tabindex="${key===k?0:-1}" data-action="home-tab" data-value="${k}"><span class="home-tab-icon tab-${k}">${icon(g.icon||tabArt[k]?.[0]||'gift')}</span><span class="home-tab-label">${esc(g.label).replace(/\n/g,'<br>')}</span></button>`).join('')}</nav>`;const surveyCTA=link(`<span class="survey-cta-icon">${icon('survey')}</span><span><small>スキマ時間に、かんたん回答</small><b>アンケート回答で<br>ポイントゲット</b></span>${icon('arrow')}`,'home/survey','survey-cta');const content=key==='chat'?chatContent():key==='daily'?`${topBannerView()}${missionCard()}${videoSection()}${surveyCTA}`:key==='steps'?`${walkSection()}${campaignBanner('steps')}<section class="section"><h2>毎日の一歩を、ポイントに。</h2><p class="section-sub">歩数の目標を達成したら、ポイントを受け取りましょう。</p></section>`:key==='survey'?`<section class="section survey-section">${sectionHead('アンケートでためる','surveys')}${surveyCards(displaySurveys())}${!state.user.profile?button('プロフィールを登録する','profile','btn primary wide'):''}</section>`:categoryContent(key);return `${header()}${tabs}<main class="home home-panel" id="home-panel" role="tabpanel" aria-labelledby="tab-${key}" tabindex="0">${content}</main>${nav()}`;}
function chatAvatar(cls=''){return `<span class="chat-avatar ${cls}">${mascot()}</span>`;}
function chatContent(){const topic=chatTopics.find(t=>t.id===route()[2]);const sessions=state.chatSessions||{};
 if(!topic)return `<section class="chat-intro"><span class="hero-eyebrow">TALK & DISCOVER</span><h2>おしゃべりから、<br>ぴったりのおトク。</h2><p>気になるテーマを選んで、タップで回答。</p>${chatAvatar()}</section><div class="chat-topic-list">${chatTopics.map(t=>{const answers=sessions[t.id]||[];const p=chatProgress(t,answers);return link(`<span class="chat-topic-art ${t.color}">${chatAvatar()}<i>${icon(t.icon)}</i></span><span class="chat-topic-copy"><small>${t.tag} · 約1分 / 2問</small><b>${t.title}</b><span>${t.lead}</span><em>${p.result?'回答済み・結果を見る':answers.length?'続きから回答':'チャットをはじめる'} ${icon('arrow')}</em></span>`,'home/chat/'+t.id,'chat-topic');}).join('')}</div><p class="chat-disclaimer">回答はこのブラウザに保存されます。<br>会話・掲載サービスはデモです。</p>`;
 const answers=sessions[topic.id]||[];const progress=chatProgress(topic,answers);const bot=text=>`<div class="chat-line bot">${chatAvatar()}<div class="chat-bubble">${esc(text)}</div></div>`;const list=(progress.result||[]).map(id=>visibleOffers(state).find(o=>o.id===id)).filter(Boolean);
 return `<div class="chat-room ${topic.color}"><div class="chat-room-head">${link(icon('back')+'テーマ一覧','home/chat','text-link')}<span>${progress.result?'回答完了':`${answers.length+1} / 2問`}</span></div><h2 class="chat-room-title">${topic.title}</h2><div class="chat-transcript" role="log" aria-label="チャットの会話" aria-live="polite">${bot('こんにちは！タメルコ案内係です。2つの質問で、あなたの気分に合うサービスを探しましょう。')}${progress.messages.map(m=>`${bot(m.question)}<div class="chat-line user"><div class="chat-bubble">${esc(m.answer)}</div></div>${m.reply?bot(m.reply):''}`).join('')}${progress.node?bot(progress.node.question):bot('回答ありがとう！気になるサービスは、条件を確認してから利用してくださいね。')}</div>${progress.result?`<section class="chat-results"><span class="chat-result-label">${icon('gift')}あなたへのおすすめ <em class="pr">PR</em></span>${list.length?`<div class="chat-offer-list">${list.map(o=>`<div class="chat-offer">${offerCard(o)}<p>ポイントは案件ごとの条件達成・承認後に付与されます。</p></div>`).join('')}</div>`:empty('現在、紹介できる案件はありません','ほかのテーマも試してみてください。','gift')}<p class="tiny">チャットへの回答だけではポイントは付与されません。</p>${link('ポイントがたまるアンケートへ','home/survey','btn primary wide')}${button('もう一度回答する','chat-reset','text-link wide',`data-id="${topic.id}"`)}</section>`:`<div class="chat-answer-box" id="chat-answers"><span>回答を選んでください</span><div class="chat-choices">${progress.node.choices.map((c,i)=>button(`<i>${String.fromCharCode(65+i)}</i>${esc(c.label)}`,'chat-answer','chat-choice',`data-id="${topic.id}" data-step="${answers.length}" data-index="${i}"`)).join('')}</div></div>`}</div>`;
}
function highOffers(){return visibleOffers(state).filter(o=>o.category==='金融'||o.base>=80000);}
function collectionPage(quick=false){const title=quick?'すぐできる':'高還元';const list=highOffers();return `${header(title)}<main>${campaignBanner(quick?'quick':'high')}<section class="section">${sectionHead(quick?'すぐできる案件':'高額でためる',undefined,'','あなたにオススメ')}<div class="offer-rows">${list.map(offerRow).join('')}</div>${!list.length?empty('現在、表示できる案件はありません','案件が追加されるまでお待ちください。'):''}</section>${note}</main>${nav()}`;}
function invitePage(){return `${header('友達招待')}<main class="invite-page"><section class="invite-hero"><span class="hero-eyebrow">WITH FRIENDS</span>${mascot('invite-mascot')}<h2>おトクな毎日を、<br>友達といっしょに。</h2><p>タメルコを、あなたの友達にも紹介しよう。</p></section><section class="section invite-code"><span class="small-label">あなたの紹介コード（サンプル）</span><strong>TAMERUKO-DEMO</strong>${button('紹介コードをコピー','copy-invite','btn primary wide')}<p class="tiny">このコードは画面確認用です。実際の招待には使えません。</p></section><section class="section"><h2>友達招待の流れ</h2><ol class="steps"><li><b>紹介コードをコピー</b><span>上のボタンからコードをコピーします。</span></li><li><b>友達にコードを伝える</b><span>いつものメッセージアプリで紹介します。</span></li><li><b>友達がタメルコをはじめる</b><span>登録時に紹介コードを入力します。</span></li></ol></section><section class="section"><h2>よくある質問</h2><details class="invite-faq"><summary>招待特典はありますか？</summary><p>特典の内容・付与条件は準備中です。</p></details><details class="invite-faq"><summary>この画面から友達を招待できますか？</summary><p>現在はモック画面です。招待の登録や特典の付与は行われません。</p></details></section></main>${nav()}`;}

// ===== 今日できること =====
function missions(){const t=todayTasks(state);return `${header('今日できること','home')}<main><section class="section"><p class="lead">今日できるお仕事 <b>${t.count}</b>件・最大 ${money(t.potential,'m-inline')}</p><p class="section-sub">毎日のタスクと、期間限定のお仕事。獲得条件・承認時期は案件ごとに異なります。</p><div class="task-list">${t.items.map(x=>{const inner=`<span class="m-icon ${x.kind} ${x.state!=='todo'?'lit':''}">${icon(kindIcon[x.kind])}</span><div class="m-text"><b>${esc(x.title)}${x.pr?'<em class="pr">PR</em>':''}</b><small>${esc(x.sub)}</small></div><div class="row-right">${x.state==='claimed'?`<span class="pill done small">${icon('check')}受取済み</span>`:x.state==='achieved'?button(`${icon('gift')}受け取る`,'claim-mission','pill lime small',`data-id="${x.id}"`):x.rate?rate(x.rate,'m-row'):money(x.reward,'m-row')}</div>${x.state==='todo'?icon('arrow','chev'):''}`;const act={steps:'go-walk',video:'video'}[x.kind];return x.state!=='todo'?`<div class="task-row ${x.state}">${inner}</div>`:act?`<button class="task-row" data-action="${act}">${inner}</button>`:`<a class="task-row" href="#${x.to}">${inner}</a>`;}).join('')}</div><p class="tiny">定率還元・追加ボーナスは合計に含みません。ポイントは付与予定として登録され、判定後に交換可能になります。</p></section>${note}</main>${nav()}`;}

// ===== 探す =====
function offerCard(o){const t=offerTerms(state,o.id);return link(`<div class="ocard-logo">${logo(o)}${t.slot&&t.rewardMode==='flat'&&t.reward>o.base?'<span class="badge-up">期間限定UP</span>':''}<em class="pr">PR</em></div><div class="ocard-body"><span class="meta">${o.category}</span><h3>${esc(o.name)}</h3><p>${esc(o.condition)}</p>${t.slot&&t.rewardMode==='flat'&&t.reward>o.base?`<del>${yen(o.base)}円相当</del>`:''}<div class="hcard-foot">${rewardText(t,'m-hcard')}<span class="tag-lime">${esc(o.cost)}</span></div></div>`,`offer/${o.id}`,'ocard');}
function offerNav(active){return `<nav class="sub-tabs" aria-label="探すナビ">${button('おすすめ','offer-reset',active==='offers'?'active':'')}${link('マイ案件','mycases',active==='mycases'?'active':'')}</nav>`;}
const guideButton=()=>button(icon('question'),'offer-guide','icon-button','aria-label="獲得までの流れ"');
function offerList(){const [,cat]=route();if(cat){category=cat;history.replaceState(null,'','#offers');}const cats=screenGroups(state,'tametoku_quick').map(g=>[g.category,g.icon||'gift',g.name]).filter(([c])=>state.persona!=='card'||c!=='金融');const items=visibleOffers(state).filter(o=>(category==='すべて'||o.category===category)&&(!search||`${o.name}${o.category}${o.condition}`.includes(search)));return `${header('探す',undefined,guideButton())}${offerNav('offers')}<main><form class="search-box" id="search-form">${icon('search')}<input aria-label="案件を検索" name="search" placeholder="ショップ・サービスを検索" value="${esc(search)}"><button aria-label="検索する">検索</button></form>${pillTicker()}<div class="chips" aria-label="カテゴリ">${[['すべて','','すべて'],...cats].map(([c,,n])=>button(esc(n),'category','chip '+(c===category?'active':''),`data-value="${c}" aria-pressed="${c===category}"`)).join('')}</div>${category==='すべて'&&!search?challengeSection(3):''}<section class="section"><div class="section-head"><h2>${category==='すべて'?'いま注目の案件':category+'でためる'}</h2><span class="meta">${items.length}件</span></div>${items.length?`<div class="ocard-grid">${items.map(offerCard).join('')}</div>`:empty('該当する案件がないようです','現在、お探しの条件に該当する案件はありません。','search')}${!state.user.installUnlocked?'<p class="tiny">インストール案件は、動画リワードを同じ日に5回視聴すると表示されます。</p>':''}</section><section class="section">${link(`${icon('bag')}<span><b>マイ案件を確認</b><small>チャレンジした案件の達成進捗が分かります</small></span>${icon('arrow')}`,'mycases','info-card')}</section>${note}</main>${nav()}`;}
// ===== 特集ページ（ディープリンク feature/<id>。案件の集約、または 1 案件の特集）=====
function featurePage(id){const f=featureById(state,id);if(!f)return `${header('特集','home')}<main>${empty('この特集は終了しました','ご不明な点は、ポイントに関する注意事項をご確認ください。','clock')}${link('探すで案件を探す','offers','btn primary wide')}</main>${nav()}`;const list=f.offerIds.map(x=>offers.find(o=>o.id===x)).filter(Boolean);
 if(f.kind==='single'&&list[0]){const o=list[0];const t=offerTerms(state,o.id);return `${header('特集','home')}<main><section class="feature-hero single">${logo(o,'detail-logo')}<span class="hero-eyebrow">PICK UP<em class="pr">PR</em></span><h2>${esc(f.title)}</h2><p>${esc(f.lead)}</p><div class="detail-price">${rewardText(t,'m-detail')}</div>${link(`案件の詳細を見る${icon('arrow')}`,`offer/${o.id}`,'btn primary wide')}<p class="tiny">${esc(f.note||'')}</p></section><section class="section"><h2>この案件について</h2><p class="cond"><b>【獲得条件】</b>${esc(o.condition)}</p><p class="cond"><b>【目安】</b>${esc(o.time)}</p><p class="cond">${esc(o.description)}</p></section>${challengeFor(state,o.id)?challengeSection(1,false):''}${note}</main>${nav()}`;}
 return `${header('特集','home')}<main><section class="feature-hero"><span class="hero-eyebrow">特集<em class="pr">PR</em></span><h2>${esc(f.title)}</h2><p>${esc(f.lead)}</p><p class="tiny">${esc(f.note||'')}　${list.length}件</p></section><section class="section"><div class="ocard-grid">${list.map(offerCard).join('')}</div></section><section class="section">${link(`${icon('gift')}<span><b>ほかの案件も見る</b><small>探すでカテゴリから探す</small></span>${icon('arrow')}`,'offers','info-card')}</section>${note}</main>${nav()}`;}
function challengesPage(){const list=challengeSlots(state);return `${header('チャレンジボーナス','offers')}<main><section class="ch-hero"><div><span class="hero-eyebrow">CHALLENGE BONUS</span><h2>みんなで達成して、<br>ボーナスをもらおう。</h2><p>開催中 ${list.length}件・参加人数が目標に達すると全員にボーナス</p></div>${mascot('intro-mascot')}</section><section class="section">${list.length?`<div class="ch-grid">${list.map(challengeCard).join('')}</div>`:empty('開催中のチャレンジはありません','次回の開催をお待ちください。','spark')}</section><section class="section"><h2>チャレンジボーナスのしくみ</h2><ol class="steps"><li><b>対象案件にチャレンジ</b><span>いつも通り「チャレンジする」からサービスを利用します。</span></li><li><b>期間内にみんなで目標人数を達成</b><span>参加人数が目標に達すると成立。達成後に利用した方も対象です。</span></li><li><b>通常報酬の承認後にボーナス付与</b><span>ボーナスは付与予定として登録され、審査後に交換可能になります。否認の場合は対象外です。</span></li></ol><p class="tiny">目標未達の場合はボーナスなし（通常報酬は条件どおり付与）。予算上限により早期終了する場合があります。参加人数はデモ値です。※本機能は現行仕様（poikatsu-spec）にない新機能の提案です。</p></section>${note}</main>${nav()}`;}

// ===== 案件詳細（spec affiliate-detail）=====
function detail(id){const o=offers.find(x=>x.id===id);if(!o)return `${header('案件詳細','offers')}<main>${empty('お探しの案件が見つかりませんでした','ご不明な点は、ポイントに関する注意事項をご確認ください。')}${button('ポイント獲得に関する注意事項','caution','btn secondary wide')}</main>${nav()}`;const t=offerTerms(state,id),s=t.slot,cv=caseFor(state,id),entry=state.user.entries[id];const c=t.challenge,ach=challengeAchieved(c),joined=cv?.challengeId&&cv.challengeId===c?.id;const cs=challengeState(state,id);
 const surCard=o.sur?`<section class="section sur-card"><div class="section-head"><h2>${cv&&cv.paidStages>=o.sur.length?'すべて達成完了':'すべての条件を達成で'}</h2>${money(o.sur.reduce((a,x)=>a+x.reward,0),'m-row')}</div><div class="sur-list-head"><b>達成リスト</b><span class="meta">${cv?.paidStages||0} / ${o.sur.length}</span></div><ul class="sur-list">${o.sur.map((st,i)=>`<li class="${cv&&cv.paidStages>i?'done':''}"><span class="sur-state">${cv&&cv.paidStages>i?icon('check')+'達成済み':'未達成'}</span><b>${esc(st.label)}</b>${money(st.reward,'m-hcard')}</li>`).join('')}</ul></section>`:'';
 const footer=cs==='sur-challenging'?button('チャレンジ中','noop','btn primary wide','disabled'):t.entryRequired&&!entry?button('エントリーする','entry','btn primary wide',`data-id="${id}"`):button(`チャレンジする${icon('external')}`,'challenge','btn primary wide',`data-id="${id}"`);
 return `${header('案件詳細','offers')}<main class="detail"><div class="detail-hero">${logo(o,'detail-logo')}<div><span class="meta">${o.category}<em class="pr">PR・サンプル案件</em></span><h2>${esc(o.name)}</h2><p>${esc(o.description)}</p></div></div><section class="section detail-summary"><div class="tags"><span class="tag">${o.category}</span>${s?'<span class="tag warm">期間限定UP</span>':''}${t.entryRequired?'<span class="tag warm">エントリー制</span>':''}${o.sur?'<span class="tag">SUR</span>':''}${c?'<span class="tag challenge-tag">チャレンジボーナス</span>':''}<span class="tag-lime">${esc(o.cost)}</span></div><div class="detail-price">${s&&t.rewardMode==='flat'&&t.reward>o.base?`<div class="was"><span>通常</span><del>${yen(o.base)}円相当</del>${icon('arrow')}</div>`:''}${rewardText(t,'m-detail')}</div><div class="condition-lead">${icon('check')}<b>${esc(o.condition)}</b></div><p class="deadline">${icon('clock')}目安：${esc(o.time)}${s?`　期限：${s.end.replaceAll('-','/')}`:''}</p>${s?.entryRequired?'<div class="entry-note">利用前のエントリーが必要です。エントリー後に「チャレンジする」からサービスをご利用ください。</div>':''}${cv?`<div class="status-note ${cv.status}">${icon('info')}<span>成果ステータス：<b>${statusLabel[cv.status]}</b>（${dateLabel[cv.status]} ${cv.date}）　${link('マイ案件で確認',`mycases`,'text-link')}</span></div>`:''}</section>
 ${surCard}
 ${c?`<section class="section challenge"><div class="ch-head">${icon('spark')}<h2>チャレンジボーナス</h2><span class="tag ${ach?'':'warm'}">${ach?'達成！':daysLeft(state,c)<=1?'終了間近':`あと${daysLeft(state,c)}日`}</span>${button('しくみ','challenge-guide','text-link small-link')}</div><p>期間内に参加人数が${c.challengeGoal.toLocaleString()}人に達すると、参加者全員に通常報酬とは別に<b>+${yen(c.bonus)}円相当</b>。${ach?'目標を達成しました。今からチャレンジしても対象です。':'達成後にチャレンジした方も対象です。'}</p><div class="challenge-count"><b>${c.participants.toLocaleString()}</b><span> / ${c.challengeGoal.toLocaleString()}人参加中</span></div><progress max="${c.challengeGoal}" value="${Math.min(c.participants,c.challengeGoal)}"></progress><p class="tiny">${ach?'':'あと'+Math.max(0,c.challengeGoal-c.participants).toLocaleString()+'人で達成。'}${c.end.replaceAll('-','/')}まで。ボーナスは通常報酬の承認後に付与予定として登録。否認の場合は対象外。参加人数はデモ値です。</p>${joined?`<div class="info-box">${cv.bonusPaid?'チャレンジボーナスを付与予定に登録しました。':'このチャレンジに参加中です。成果の承認後、達成していればボーナスが付与されます。'}</div>`:''}</section>`:''}
 <section class="section"><h2>お小遣いがたまるまで</h2><ol class="steps">${t.entryRequired?`<li class="${entry?'done':''}"><b>${entry?'エントリー済み':'エントリーする'}</b><span>サービスを利用する前に</span></li>`:''}<li class="${cv?'done':''}"><b>「チャレンジする」からサービスを利用</b><span>${esc(o.condition)}。外部ブラウザでサービスのページを開きます</span></li><li class="${cv&&cv.status==='approved'?'done':''}"><b>成果の確認・承認</b><span>${esc(o.time)}。承認されると付与予定（準備中）に登録されます</span></li><li><b>審査後に交換可能へ</b><span>案件のポイントは審査を経て交換可能になります。マイ案件から状況を確認できます</span></li></ol></section>
 <section class="section"><h2>ポイント獲得条件</h2><p class="cond"><b>【獲得条件】</b>${esc(o.condition)}が対象です。</p><p class="cond"><b>【獲得対象外】</b>キャンセル・重複利用・条件未達成の場合は対象外です。途中で別サイトを経由すると成果を確認できない場合があります。</p>${button('ポイント獲得に関する注意事項','caution','btn secondary wide')}</section>
 <section class="section"><h2>案件概要</h2><p class="cond">${esc(o.description)}</p></section>${note}
 <div class="sticky-action">${footer}${entry&&!cv?'<small class="green">エントリー済み・「チャレンジする」から利用すると対象です</small>':''}${cv&&!o.sur&&cv.status!=='challenging'?'<small class="tiny">この案件は再度チャレンジできます（成果ごとにマイ案件へ表示）</small>':''}</div></main>${nav()}`;}

// ===== マイ案件（spec affiliate-my-affiliates：4 ステータスタブ、成果ごとに 1 件）=====
function caseTabs(){return `<nav class="sub-tabs case-tabs four" aria-label="成果ステータス">${Object.entries(statusLabel).map(([v,l])=>button(l,'case-tab',caseTab===v?'active':'',`data-value="${v}" aria-pressed="${caseTab===v}"`)).join('')}</nav>`;}
const helpNote=()=>`<div class="help-note"><span>案件進捗や結果についてお困りの方はヘルプをご確認ください</span>${button('ヘルプを確認','case-help','btn secondary small')}</div>`;
function myCases(){const list=state.user.cases.filter(c=>c.status===caseTab).slice().reverse();return `${header('マイ案件','offers')}${caseTabs()}<main><section class="section">${caseTab!=='approved'?helpNote():''}<div class="section-head"><h2>${statusLabel[caseTab]}の案件</h2><span class="meta">${list.length}件</span></div>${list.length?list.map(c=>{const o=offers.find(o=>o.id===c.offerId);return `<article class="case-card"><a href="#offer/${c.offerId}" class="case-head">${logo(o,'row-logo')}<div><span class="tag ${c.status==='approved'?'':c.status==='rejected'?'gray':'warm'}">${statusLabel[c.status]}</span><h3>${esc(c.name)}</h3><span class="meta">${dateLabel[c.status]} ${c.date}</span></div>${icon('arrow','chev')}</a>${o.sur&&c.status==='challenging'?`<div class="level-track">${o.sur.map((st,i)=>`<div class="${c.paidStages>i?'done':''}"><span>${c.paidStages>i?icon('check'):i+1}</span><small>${esc(st.label.replace('到達',''))}</small></div>`).join('')}</div><p><b>${c.paidStages>=o.sur.length?'すべての条件を達成しました！':`次は${o.sur[c.paidStages].label}`}</b></p><p class="tiny">段階ごとに承認され、付与予定に登録されます。</p>`:c.status!=='challenging'?`<p>${esc(c.condition)}</p>`:''}${c.challengeId?(()=>{const ch=state.slots.find(x=>x.id===c.challengeId);if(!ch)return '';const ach=challengeAchieved(ch);return `<div class="ch-status ${ach?'achieved':''}">${icon('spark')}<span><b>チャレンジボーナス +${yen(c.challengeBonus)}円相当</b><small>${c.status==='rejected'?'否認のため対象外':c.bonusPaid?'付与予定に登録済み':ach?(c.status==='approved'?'達成・承認済み。付与予定に登録されます':'達成！成果の承認後に付与'):`達成待ち ${ch.participants.toLocaleString()} / ${ch.challengeGoal.toLocaleString()}人・${ch.end.slice(5).replace('-','/')}まで`}</small></span></div>`;})():''}${c.status!=='rejected'?`<div class="case-foot"><span>報酬${c.rewardMode==='rate'?'（購入額に応じて）':''}</span>${c.rewardMode==='rate'?rate(c.reward,'m-row'):money(c.reward,'m-row')}</div>`:''}</article>`;}).join(''):empty('まだ案件はないようです','マイ案件では、あなたがチャレンジした案件の達成進捗を確認することができます。','bag')}${link('案件を探す','offers','btn secondary wide')}</section>${ad('mrec','MREC（my_affiliates_bottom）')}${note}</main>${nav()}`;}

// ===== アンケート =====
function surveyRow(q){const done=state.user.answered.includes(q.id);return link(`<span class="m-icon survey ${q.type==='main'?'main':''}">${icon(q.type==='main'?'spark':'survey')}</span><div class="row-main"><span class="meta">${q.label}・${q.minutes}分</span><h3>${esc(q.title)}</h3>${q.parent?'<small class="invited">事前調査にご協力いただいた方へ</small>':''}</div><div class="row-right">${money(surveyReward(state,q),'m-row')}</div>${icon('arrow','chev')}`,done?'surveys':`answer/${q.id}`,'task-row');}
function surveyList(){const avail=displaySurveys().filter(q=>surveyFilter==='すべて'||surveyFilter==='スクリーニング'&&q.type==='screening'||surveyFilter==='本調査'&&q.type==='main');return `${header('アンケートでためる','home')}<main><section class="survey-intro"><div><span class="hero-eyebrow">あなたの声を、次の一歩に。</span><h2>答えるたびに、<br>お小遣いがたまる。</h2><p>短い調査から、じっくり答える本調査まで。</p></div>${mascot('intro-mascot')}</section><div class="benefits"><span>${icon('clock')}スキマ時間に</span><span>${coin()}回答完了で付与予定に登録</span></div><section class="section"><button class="profile-card" data-action="profile"><div class="ring">${state.user.profile?'100':'25'}<small>%</small></div><span><b>あなたに合う調査を届けます</b><small>${state.user.profile?'プロフィール登録済み':'プロフィールをあと3項目登録'}</small></span>${icon('arrow','chev')}</button><div class="chips" aria-label="アンケートの種類">${['すべて','スクリーニング','本調査'].map(c=>button(c,'survey-filter','chip '+(c===surveyFilter?'active':''),`data-value="${c}" aria-pressed="${c===surveyFilter}"`)).join('')}</div><div class="section-head"><h2>回答できるアンケート</h2><span class="meta">${avail.length}件</span></div><div class="task-list">${state.scenario==='empty'?empty('アンケートがありません','アンケートが届くと、こちらに表示されます。'):state.scenario==='error'?`${FAIL}${button('再読み込み','retry','btn secondary wide')}`:avail.length?avail.map(surveyRow).join(''):empty('アンケートがありません','アンケートが届くと、こちらに表示されます。')}</div><p class="tiny">表示ポイントは報酬額（円）×ユーザー還元率（スクリーニング ${surveyRate(state,'screening')}%・本調査 ${surveyRate(state,'main')}%【仮値】）で換算しています。</p></section><section class="section journey"><h2>回答の先に、次のチャンス。</h2><div class="journey-steps"><span class="active">スクリーニング</span>${icon('arrow')}<span>本調査</span>${icon('arrow')}<span class="future">インタビュー</span></div><p>条件に合う方には、本調査をご案内します。インタビューへのご案内は今後対応予定です。</p></section>${state.user.answered.length?`<section class="section">${sectionHead('回答済み')}<div class="history-list">${state.user.answered.map(id=>`<div><span>${esc(surveys.find(x=>x.id===id)?.title)}</span><span class="tag warm">回答済み</span></div>`).join('')}</div></section>`:''}${ad('mrec','MREC（survey_list_bottom）')}${note}</main>${nav()}`;}
function answerPage(id){const q=surveys.find(x=>x.id===id);if(!q||!displaySurveys().some(x=>x.id===id))return`${header('アンケート','surveys')}<main>${empty('このアンケートは回答できません','回答済み、または配信条件の対象外です。')}</main>${nav()}`;if(!answerDraft||answerDraft.id!==id)answerDraft={id,step:-1,answers:[]};const step=answerDraft.step;
 if(step<0)return `${header('アンケート詳細','surveys')}<main><section class="survey-start">${mascot('start-mascot')}<span class="tag ${q.type==='main'?'warm':''}">${q.label}</span><h2>${esc(q.title)}</h2><p>あなたのお考えをお聞かせください。</p><div class="facts"><div>${icon('clock')}<span>回答時間<b>${q.minutes}分</b></span></div><div>${coin()}<span>獲得できるポイント${money(surveyReward(state,q),'m-fact')}</span></div></div><p class="explain">実際のアプリでは、外部の回答ページをアプリ内ブラウザで開きます。回答完了の通知を受け取るとポイントが付与予定として登録され、判定後に交換可能になります。</p>${button('回答をはじめる（デモ）','begin-survey','btn primary wide',`data-id="${id}"`)}<p class="tiny">この試作では架空の設問に回答します。外部へ送信されません。</p></section>${note}</main>${nav()}`;
 return `${header('アンケート回答','surveys')}<main><section class="answer"><div class="q-count"><span>${q.label}</span><b>${step+1}<small> / ${q.questions.length}</small></b></div><progress max="${q.questions.length}" value="${step+1}"></progress><span class="hero-eyebrow">QUESTION ${String(step+1).padStart(2,'0')}</span><h2>${esc(q.questions[step])}</h2><p class="section-sub">最も近いものを1つ選んでください。</p><div class="options">${q.choices[step].map((a,i)=>button(`<span class="radio"></span>${esc(a)}`,'answer','option '+(answerDraft.answers[step]===i?'selected':''),`data-value="${i}" aria-pressed="${answerDraft.answers[step]===i}"`)).join('')}</div><div class="answer-buttons">${step?button('前の質問','previous-question','btn secondary'):''}${button(step===q.questions.length-1?'回答を送信する':'次の質問へ','next-question','btn primary',answerDraft.answers[step]===undefined?'disabled':'')}</div>${button('回答を中断する','interrupt','text-link wide')}<p class="tiny">個人情報は入力しないでください。回答はこの試作内でのみ使用します。</p></section>${note}</main>`;}
function completePage(id){const q=surveys.find(x=>x.id===id);const h=state.user.history.find(x=>x.desc===q?.title&&x.category==='SURVEY');return `${header('回答完了','surveys')}<main><section class="complete">${mascot('start-mascot')}<span class="hero-eyebrow">THANK YOU!</span><h2>ご協力ありがとうございます。</h2><p>回答完了の通知を受け取りました。</p><div class="receipt"><span>準備中のポイント</span>${money(h?.amount||0,'m-receipt')}<p>付与予定として登録されました。ポイント自動判定で確定すると「交換可能」に移ります。</p></div>${id==='s1'&&availableSurveys(state).some(x=>x.id==='s3')?`<a href="#answer/s3" class="invitation"><span class="tag warm">あなたへのご案内</span><h3>本調査が届きました</h3><p>これからの買い物と暮らし</p><div>${money(surveyReward(state,surveys[2]),'m-row')}<span class="pill dark">回答する ${icon('arrow')}</span></div></a>`:''}${link('ほかのアンケートを見る','surveys','btn primary wide')}${link('ホームに戻る','home','text-link wide')}</section>${note}</main>${nav()}`;}

// ===== マイページ（spec my-page）=====
function mypage(){const c=exchangeConditions(state);const guest=isGuest(state);const pend=state.user.pendings.slice().reverse();const hist=state.user.history.filter(h=>h.status!=='pending').slice(0,5);const active=state.user.cases.filter(x=>['challenging','judging'].includes(x.status)).length;
 const pointArea=`<span class="small-label">あなたのポイント</span>${money(total(state),'m-balance')}${!guest&&state.user.pending>0?`<div class="wallet-lines"><span>準備中 <b>${yen(state.user.pending)}</b>円相当</span><span>交換可能 <b>${yen(state.user.approved)}</b>円相当</span></div>`:''}<p class="exchange-state ${c.text.state}">${c.text.label}</p>`;
 const card=guest?`<section class="wallet guest"><button class="text-link" data-action="guest-help">${icon('question')}ゲストユーザーについて</button>${pointArea}<div class="guest-promo"><b>会員登録・ログインでできること</b><ul><li>ポイントを安全に保存</li><li>ドットマネーへのポイント交換</li></ul>${button('会員登録・ログイン','guest-signup','btn primary wide')}</div><p class="tiny">失効予定はゲストには表示しません。</p></section>`:`<section class="wallet">${pointArea}<div class="wallet-actions">${button(`${icon('wallet')}ドットマネーに交換<em class="fee">手数料無料</em>`,'exchange','btn primary',c.canExchange?'':'disabled')}${button('内訳を見る','balance','btn secondary')}</div><p class="tiny">${icon('check')}最低交換 ${pt(L(state).minAmount)}pt（${yen(L(state).minAmount)}円相当）・交換単位 ${pt(L(state).unit)}pt。SMS本人確認${state.user.sms?'済み':'が必要'}</p>${button(`ドットマネー通帳を見る${icon('external')}`,'dotmoney','text-link')}<p class="tiny">ドットマネーの残高はアプリでは表示しません。</p><p class="tiny">失効予定：0pt（確定から N ヶ月後の月末に失効。N は運用設定）</p></section>`;
 return `${header('マイページ')}<main>${card}<div class="menu-grid">${link(`${icon('bag')}<b>マイ案件</b><small>${active}件進行中</small>`,'mycases')}${link(`${icon('survey')}<b>アンケート</b><small>${displaySurveys().length}件届いています</small>`,'surveys')}${button(`${icon('chart')}<b>実績レポート</b><small>今日の実績カード</small>`,'report','')}${button(`${icon('user')}<b>プロフィール</b><small>${state.user.profile?'登録済み':'あと3項目'}</small>`,'profile','')}</div><section class="section">${sectionHead('最近の履歴',null)}${pend.length||hist.length?`<div class="history-list">${pend.map(p=>`<div><div><span>${esc(p.title)}</span><small>${esc(p.desc)}・${p.date.replaceAll('-','/')}・<em class="prep">準備中</em>${p.review==='manual'?'（審査）':''}</small></div><b class="pending">+${yen(p.amount)}</b></div>`).join('')}${hist.map(h=>`<div><div><span>${esc(h.title)}</span><small>${esc(h.desc)}${h.desc?'・':''}${h.date.replaceAll('-','/')}</small></div><b class="${h.amount<0?'minus':''}">${h.amount>0?'+':''}${yen(h.amount)}</b></div>`).join('')}</div>${button(`実績レポートを見る${icon('arrow')}`,'report','btn secondary wide')}`:empty('まだ履歴がありません','ミッションやアンケートでためると、ここに表示されます。','list')}</section><section class="section">${button(`${icon('wallet')}<span><b>ためた分を、手数料無料で。</b><small>ドットマネーへの交換について</small></span>${icon('arrow')}`,'savings','info-card')}</section><section class="section settings"><h2>設定・サポート</h2>${[['ヘルプ','help'],['お問い合わせ','contact'],['アカウント情報',''],['トラッキング設定',''],['プライバシーポリシー',''],['ライセンス情報',''],['利用規約',''],['アクセスデータの利用','']].map(([l,a])=>a?button(`${l}${icon('arrow','chev')}`,a,'settings-row'):`<div class="settings-row">${l}${icon('arrow','chev')}</div>`).join('')}${button(`お知らせ${icon('arrow','chev')}`,'notifications','settings-row')}</section>${ad('mrec','MREC（my_page_bottom）')}<p class="tiny center">タメルコ v2 モック / © サンプル</p>${note}</main>${nav()}`;}

// ===== 状態表示（spec：セクション単位が正。モックでは画面全体で再現）=====
function stateScreen(page){const names={home:'ホーム',high:'高還元',quick:'すぐできる',invite:'友達招待',offers:'探す',surveys:'アンケート',mycases:'マイ案件',offer:'案件詳細',mypage:'マイページ'};const title=names[page];if(!title||viewState==='normal'||viewState==='ended'&&!['mycases','offer'].includes(page))return null;
 const top=(page==='home'||page==='mypage'||page==='offers'?header(page==='home'?'':title,undefined,page==='offers'?guideButton():''):header(title,page==='offer'?'offers':'home'))+(page==='mycases'?caseTabs():page==='offers'?offerNav('offers'):'');
 if(viewState==='loading')return `${top}<main class="state-page"><div role="status" class="loading-caption">読み込み中（スケルトン）</div><div class="skeletons" aria-hidden="true"><div class="skeleton banner"></div>${[1,2,3].map(()=>'<div class="skeleton-row"><i class="skeleton"></i><div><i class="skeleton"></i><i class="skeleton"></i></div></div>').join('')}</div></main>${nav()}`;
 if(viewState==='error')return `${top}<main class="state-page"><div class="empty">${icon('info')}<h3>情報を取得できませんでした。</h3></div>${button('再読み込み','restore-view','btn primary wide')}<p class="tiny">spec：取得失敗はセクション単位で表示し、他のセクションには影響しません。</p></main>${nav()}`;
 if(viewState==='ended')return `${top}<main class="state-page">${empty('お探しの案件が見つかりませんでした','ご不明な点は、ポイントに関する注意事項をご確認ください。','clock')}${button('ポイント獲得に関する注意事項','caution','btn secondary wide')}${button('マイ案件を確認する','restore-cases','btn primary wide')}</main>${nav()}`;
 return `${top}<main class="state-page">${empty(page==='mycases'?'まだ案件はないようです':page==='surveys'?'アンケートがありません':'該当する案件がないようです',page==='mycases'?'マイ案件では、あなたがチャレンジした案件の達成進捗を確認することができます。':page==='surveys'?'アンケートが届くと、こちらに表示されます。':'現在、お探しの条件に該当する案件はありません。')}${button(page==='mycases'?'案件を探す':'もう一度確認する',page==='mycases'?'restore-offers':'restore-view','btn primary wide')}</main>${nav()}`;}

// ===== 外枠（画面一覧・デモ設定）=====
function inspector(){return `<aside class="inspector"><span class="hero-eyebrow">PROTOTYPE v2 / 2026.09.15</span><h1>タメルコ<br><span>現行デザイン × 新機能</span></h1><p>現状アプリの見た目を維持しつつ、<br>ブースト・マイ案件・アンケート連鎖を統合。<br>数値・条件は poikatsu-spec を優先。</p><nav aria-label="画面一覧">${[['home','home','ホーム（TOP）'],['feature/autumn-trip','ticket','特集ページ（ディープリンク）'],['missions','list','今日できること'],['offers','search','探す・案件一覧'],['high','chart','高還元'],['quick','clock','すぐできる'],['invite','gift','友達招待'],['offer/travel','bag','ブースト案件・詳細'],['offer/game','chart','SUR 案件（段階報酬）'],['challenges','spark','チャレンジボーナス'],['mycases','ticket','マイ案件・成果ステータス'],['surveys','survey','アンケート一覧'],['mypage','user','マイページ']].map(([to,ico,title])=>link(`${icon(ico)}${title}${icon('arrow')}`,to,location.hash===`#${to}`||!location.hash&&to==='home'?'current':'')).join('')}</nav><div class="scope-note"><b>spec に合わせた項目</b><ul><li>合算ポイント／準備中／交換可能</li><li>付与予定 → 自動判定／有人審査で確定</li><li>ミッションの達成と受け取りの分離</li><li>歩数は 1 回 1 マイルストーン・動画あり／なし</li><li>動画は配信可否で表示、再生済み・本日分終了</li><li>チャレンジする／挑戦中・判定中・承認・否認</li><li>最低交換 100pt・交換単位 100pt</li><li>アンケートは還元率で換算</li></ul><b>仮値（spec は運用設定）</b><ul><li>歩数 1,000 歩 × 4 回、動画 3 回</li><li>各ポイント額、還元率</li></ul></div><a href="docs/08-spec-gap.md" target="_blank">差分整理ドキュメント ↗</a><span class="inspector-bottom">架空のデータを使用しています。<br>金銭の授受・外部サービスへの接続はありません。</span></aside>`;}
function demoPanel(){const LM=L(state);return `<aside class="demo-panel"><div class="demo-title">${icon('settings')}<h2>表示・動作の確認</h2></div><p>ここはモックの検証用です。<br>アプリの画面には含みません。</p><label>画面の表示状態<select id="demo-view">${[['normal','通常'],['loading','読み込み中'],['error','取得エラー'],['empty','0件'],['ended','案件未発見（掲載終了）']].map(([v,n])=>`<option value="${v}" ${viewState===v?'selected':''}>${n}</option>`).join('')}</select></label><label>確認する日付<input type="date" id="demo-date" value="${state.date}"></label><label>利用者の状態<select id="demo-persona">${[['regular','継続利用者（成人）'],['new','新規利用者（インストール案件 未解禁）'],['minor','未成年（広告配信なし）'],['guest','ゲスト（Ameba 未連携）'],['card','クレカ案件を利用済み']].map(([v,n])=>`<option value="${v}" ${state.persona===v?'selected':''}>${n}</option>`).join('')}</select></label><label>歩数計測の連携<select id="demo-steplink">${[['linked','連携済み'],['unlinked','未連携'],['unavailable','利用不可（計測できない端末）']].map(([v,n])=>`<option value="${v}" ${state.stepLink===v?'selected':''}>${n}</option>`).join('')}</select></label><label>読み込み・交換の状態<select id="demo-scenario">${[['normal','通常'],['empty','アンケートの配信なし'],['error','読み込み・送信エラー'],['cap','日次交換総額上限に到達']].map(([v,n])=>`<option value="${v}" ${state.scenario===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="toggle-line"><span>SMS 本人確認 済み</span><input type="checkbox" id="demo-sms" ${state.user.sms?'checked':''}></label><label class="toggle-line"><span>インストール案件 解禁済み</span><input type="checkbox" id="demo-install" ${state.user.installUnlocked?'checked':''}></label><label class="toggle-line"><span>秋のおでかけブースト</span><input type="checkbox" id="demo-boost" ${state.slots.find(x=>x.id==='autumn').enabled?'checked':''}></label><label>起動時ポップアップの表示<select id="demo-popup">${[['daily','1日1回（既定）'],['always','起動ごとに毎回'],['off','表示しない']].map(([v,n])=>`<option value="${v}" ${(state.popupMode||'daily')===v?'selected':''}>${n}</option>`).join('')}</select></label><label>表示する枠<select id="demo-popup-slot">${popupSlots(state).map((x,i)=>`<option value="${x.id}">${esc(x.name)}${i===0?'（自動表示の対象）':''}</option>`).join('')||'<option value="">表示できる枠がありません</option>'}</select></label>${button('起動時ポップアップを表示する','show-popup','btn secondary wide small')}${button('本日の表示済みをリセット','reset-popup','btn secondary wide small')}<div class="demo-actions"><b>ポイントの確定</b>${button(`ポイント自動判定を実行（${state.user.pendings.filter(x=>x.review==='auto').length}件）`,'auto-review','btn secondary wide small')}${button(`有人審査で承認（案件 ${state.user.pendings.filter(x=>x.review==='manual').length}件）`,'manual-review','btn secondary wide small')}<b>歩数・動画</b>${button('歩数を1,000歩進める','add-steps','btn secondary wide small')}${button('動画を本日の上限にする','limit-video','btn secondary wide small')}<b>案件の成果（NACS の承認・否認を再現）</b>${button('最新の案件の成果を承認（SUR は1段階）','progress-demo','btn secondary wide small')}${button('最新の案件の成果を否認','reject-demo','btn secondary wide small')}<b>チャレンジボーナス</b>${button('参加人数を+500人','advance-challenge','btn secondary wide small')}${button('達成にする（全件）','achieve-challenge','btn secondary wide small')}</div><div class="demo-foot"><b>仮値（spec は運用設定のため値を書かない）</b><p>歩数 ${LM.stepGoal.toLocaleString()}歩 × ${LM.stepMax/LM.stepGoal}回／動画あり ${yen(LM.stepRewardAd)}円相当・なし ${yen(LM.stepRewardNoAd)}円相当<br>動画 ${LM.videoLimit}回 × ${yen(LM.videoReward)}円相当<br>ミッション報酬 ${state.missionDef.map(m=>`${m.title.replace('よう','')} ${yen(m.reward)}`).join('・')}円相当<br>アンケート還元率 スクリーニング ${LM.surveyRate.screening}%・本調査 ${LM.surveyRate.main}%<br>これらは <a href="../mock-admin/" target="_blank">管理画面モック</a> から変更できます</p><b>spec に明記</b><p>最低交換 ${LM.minAmount}pt・交換単位 ${LM.unit}pt<br>インストール案件解禁：同日の動画視聴 ${LM.installUnlock}回</p></div>${button('デモデータを初期化','reset','text-link wide')}</aside>`;}

// ===== 描画 =====
function render(){applyReservations(state);const [page,id]=route();document.title=`${({home:'ホーム',high:'高還元',quick:'すぐできる',invite:'友達招待',offers:'探す',offer:'案件詳細',surveys:'アンケート',answer:'回答',complete:'回答完了',mycases:'マイ案件',missions:'今日できること',mypage:'マイページ',challenges:'チャレンジボーナス',feature:'特集'})[page]||'タメルコ'} | タメルコ v2`;const views={home,high:()=>collectionPage(),quick:()=>collectionPage(true),invite:invitePage,offers:offerList,challenges:challengesPage,feature:()=>featurePage(id),offer:()=>detail(id),surveys:surveyList,answer:()=>answerPage(id),complete:()=>completePage(id),mycases:myCases,missions,mypage};const content=stateScreen(page)??(views[page]||home)();const scroll=document.querySelector('.phone-scroll')?.scrollTop||0;root.innerHTML=`<div class="mobile-demo-bar"><span>タメルコ v2・モック</span>${button('デモ設定','demo','text-link')}</div><div class="workspace">${inspector()}<div class="preview"><div class="preview-label"><span class="live-dot"></span> APP PREVIEW <span>402 × 874</span></div><div class="phone"><div class="phone-status"><span>9:41</span><div class="dynamic-island"></div><span class="status-bars">▮▮▮ <span>●</span> ▰</span></div><div class="phone-scroll">${content}</div></div><div class="preview-caption">現行アプリの配色・部品を維持 / 数値・条件は poikatsu-spec を優先（運用設定の値は仮値）</div></div>${demoPanel()}</div>`;document.querySelector('.phone-scroll').scrollTop=scroll;document.querySelector('.home-tabs [aria-selected="true"]')?.scrollIntoView({block:'nearest',inline:'nearest'});}
function showModal(title,body,cls=''){returnFocus=document.activeElement;modal.className=cls;modal.innerHTML=`<div class="modal-header"><h2>${title}</h2>${button(icon('close'),'close','icon-button','aria-label="閉じる"')}</div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
function close(){modal.close();returnFocus?.focus?.();}
function save(){localStorage.setItem(KEY,JSON.stringify(state));}
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3400);}
function go(to){location.hash=to;}
function updated(message){save();render();if(message)toast(message);}
// spec point-earned-dialog：「おめでとうございます！」「ポイント獲得」「とじる」、合算ポイント（獲得後）、バナー広告枠
function earnedDialog(amount,sub=''){showModal('おめでとうございます！',`<div class="reward-dialog">${mascot('dialog-mascot')}<span class="small-label">ポイント獲得${sub?`　${esc(sub)}`:''}</span>${money(amount,'m-balance')}<p class="tiny">付与予定（準備中）として登録されました。合算ポイント：${yen(total(state))}円相当</p>${adsAllowed(state)?ad('banner','バナー広告（points_earned_popup）'):''}${button('とじる','close','btn primary wide')}</div>`);}
function popupBanner(slot){const t=offerTerms(state,slot.destination),o=t.offer;return `<div class="popup-banner">${button(icon('close'),'close','popup-close','aria-label="閉じる"')}<div class="popup-art"><span class="hero-eyebrow">${slot.challengeGoal?'みんなでチャレンジ':'期間限定 BOOST'}<em class="pr">PR</em></span><h2>${esc(slot.title).replace(/\n/g,'<br>')}</h2>${logo(o,'popup-logo')}${mascot('popup-mascot')}</div><div class="popup-body"><p>${esc(slot.text)}</p><div class="popup-price">${slot.challengeGoal?`達成でさらに ${money(slot.bonus,'m-detail')}`:`<del>通常 ${yen(o.base)}円相当</del>${rewardText(t,'m-detail')}`}</div><span class="popup-date">${icon('clock')}${slot.end.replaceAll('-','/')}まで${slot.entryRequired?'・利用前にエントリー':''}</span><a href="#offer/${slot.destination}" class="btn primary wide" data-action="popup-go" data-slot="${slot.id}">詳しく見る</a>${button('あとで見る','close','text-link wide')}<p class="tiny">運用枠「${esc(slot.name)}」の起動時ポップアップ（spec では Braze アプリ内メッセージに相当）。</p></div></div>`;}
function showPopup(slot,{markSeen=true}={}){if(!slot)return false;returnFocus=document.activeElement;modal.className='popup';modal.innerHTML=popupBanner(slot);if(!modal.open)modal.showModal();record(state,slot.id,'imp');if(markSeen)markPopupSeen(state);save();return true;}
function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function playAd(){showModal('デモ動画を再生中',`<div class="video-screen">${icon('play')}<p>サンプル広告</p><div class="video-progress"></div></div><p class="tiny">視聴完了後にポイントを獲得できます。途中で閉じると何も起きません。</p>`);const token=crypto.randomUUID();modal.dataset.videoToken=token;await wait(2000);return modal.open&&modal.dataset.videoToken===token;}

// ===== 操作 =====
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');const slotLink=e.target.closest('[data-slot]');if(slotLink){record(state,slotLink.dataset.slot,'tap');save();}if(!el)return;const a=el.dataset.action,id=el.dataset.id;
 switch(a){
 case'noop':break;
 // --- デイリーミッション ---
 case'chat-answer':{const topic=chatTopics.find(t=>t.id===id);if(!topic)break;const sessions=state.chatSessions??={};const answers=sessions[id]||[];if(answers.length!==Number(el.dataset.step))break;sessions[id]=answerChat(topic,answers,Number(el.dataset.index));save();render();const target=document.querySelector('.chat-answer-box button,.chat-results a');target?.focus({preventScroll:true});document.querySelector('.chat-answer-box,.chat-results')?.scrollIntoView({behavior:'smooth',block:'center'});break;}
 case'chat-reset':{if(state.chatSessions)delete state.chatSessions[id];save();render();document.querySelector('.phone-scroll').scrollTop=0;break;}
 case'home-tab':go('home/'+el.dataset.value);break;
 case'copy-invite':try{await navigator.clipboard.writeText('TAMERUKO-DEMO');toast('紹介コードをコピーしました');}catch{showModal('紹介コード', '<p>コードを選択してコピーしてください。</p><input aria-label="紹介コード" value="TAMERUKO-DEMO" readonly>');}break;
 case'claim-mission':{const r=claimMission(state,id);if(r.error){toast(r.error==='ERROR_TYPE_DAILY_MISSION_TASK_ALREADY_CLAIMED'?'すでに受け取り済みです。':'このタスクはまだ達成していません。');break;}save();render();earnedDialog(r.amount,'デイリーミッション');break;}
 // --- 歩いてためる ---
 case'scroll-walk':case'go-walk':go('home/steps');break;
 case'step-select':{if(!stepsClaimable(state)){toast('獲得可能なマイルストーンがありません。');break;}const L=state.limits;showModal('ポイントをもらいましょう！',`<div class="reward-dialog step-select">${mascot('dialog-mascot')}<p>${(day(state).stepsClaimed+1)*L.stepGoal}歩のマイルストーンに到達しました。獲得方法を選んでください。</p>${adsAllowed(state)?button(`${icon('play')}動画を見ると ${yen(L.stepRewardAd)}円相当`,'step-ad','btn primary wide'):''}${button(`そのままもらうと ${yen(L.stepRewardNoAd)}円相当`,'step-noad','btn secondary wide')}${button('とじる','close','text-link wide')}<p class="tiny">1回の獲得で1マイルストーン。続けて獲得するには再度「獲得する」を押します。</p></div>`);break;}
 case'step-noad':{const amt=claimSteps(state,false);close();if(amt){save();render();earnedDialog(amt,'歩いてためる');}else toast('獲得できませんでした。');break;}
 case'step-ad':{const ok=await playAd();if(!ok)break;const amt=claimSteps(state,true);if(amt){save();render();earnedDialog(amt,'歩いてためる（動画あり）');}else{close();toast('獲得できませんでした。');}break;}
 case'walk-link':showModal('ヘルスケア連携をしましょう',`<p>端末の権限ダイアログで歩数の読み取りを許可すると、当日の歩数を取得できます（デモでは許可済みにします）。</p><div class="info-box">権限を一度拒否している場合は、端末の設定から連携をやり直します。</div>${button('許可する（デモ）','walk-link-ok','btn primary wide')}${button('OK','close','text-link wide')}`);break;
 case'walk-link-ok':state.stepLink='linked';close();updated('ヘルスケア連携が完了しました。');break;
 case'walk-help':showModal('歩いてためる',`<p>${L(state).stepGoal.toLocaleString()}歩ごとのマイルストーンに到達するとポイントを獲得できます（1日${stepMaxCount(state)}回まで）。獲得のたびに「動画を見て多くもらう」か「そのまま少なくもらう」かを選べます。</p><p>歩数は端末が計測した当日の歩数を使い、日付は JST 0:00 で切り替わります。ポイントは付与予定として登録され、判定後に交換可能になります。</p><div class="info-box">間隔・上限回数・ポイント額は運用設定です（このモックの値は仮値）。実際のヘルプは Zendesk のヘルプページで案内します。</div>${button('閉じる','close','btn primary wide')}`);break;
 // --- 動画リワード ---
 case'video':{if(!adsAllowed(state)){toast('このユーザーには動画広告を配信しません。');break;}if(videoRemaining(state)<=0){toast('本日分は終了しました。');break;}const ok=await playAd();if(!ok)break;if(claimVideo(state)){save();render();earnedDialog(L(state).videoReward,'動画を見てためる');}else{close();toast('本日の視聴は上限に達しています。');}break;}
 // --- 案件 ---
 case'entry':state.user.entries[id]={date:state.date};updated('エントリーしました。「チャレンジする」からサービスをご利用ください。');break;
 // spec affiliate-detail 4：「チャレンジする」→ 広告トラッキング確認シート → 署名付きクリック URL を取得し外部ブラウザで開く
 case'challenge':showModal('チャレンジ前のご確認',`<p>成果を正しく計測するため、次をご確認ください。</p><ul class="cond-list"><li class="ok">${icon('check')}Wi-Fi をオフにしてモバイル回線でのご利用を推奨します</li><li class="ok">${icon('check')}広告トラッキングの許可を求める場合があります（許可は必須ではありません）</li><li class="ok">${icon('check')}このあと外部ブラウザでサービスのページを開きます</li></ul><div class="info-box">${esc(offers.find(x=>x.id===id).condition)}</div>${button(`チャレンジする（外部ブラウザを開く）${icon('external')}`,'confirm-challenge','btn primary wide',`data-id="${id}"`)}<p class="tiny">クリック URL は発行から前後 30 秒のみ有効です。このモックでは外部へ移動せず、成果の発生（判定中／挑戦中）を同時に再現します。</p>`);break;
 case'confirm-challenge':try{const cv=challenge(state,id);close();if(cv){updated(`チャレンジしました。成果ステータス「${statusLabel[cv.status]}」としてマイ案件に表示します。`);go('mycases');caseTab=cv.status;render();}else toast('この案件は現在チャレンジできません。');}catch(err){toast(err.message);}break;
 case'caution':showModal('ポイント獲得に関する注意事項',`<p>ポイントは成果の承認後に付与予定として登録され、審査を経て交換可能になります。キャンセル・重複利用・条件未達成は対象外です。</p><p class="tiny">実際のアプリではヘルプページをアプリ内ブラウザで表示します。</p>${button('閉じる','close','btn primary wide')}`);break;
 case'case-tab':caseTab=el.dataset.value;render();document.querySelector(`[data-action="case-tab"][data-value="${caseTab}"]`)?.focus({preventScroll:true});break;
 case'case-help':showModal('案件の進捗・結果について',`<ol class="steps"><li><b>成果ステータスを確認</b><span>挑戦中→判定中→承認／否認の順に進みます。承認までの目安は案件詳細に記載しています。</span></li><li><b>承認後のポイント</b><span>付与予定（準備中）に登録され、審査後に交換可能へ移ります。マイ案件の「承認」表示が先になることがあります。</span></li><li><b>反映されないとき</b><span>タメルコの「チャレンジする」から利用したか、獲得条件・対象外条件をご確認ください。</span></li></ol><p class="tiny">実際のアプリではヘルプページをアプリ内ブラウザで表示します。</p>${button('閉じる','close','btn primary wide')}`);break;
 case'offer-reset':category='すべて';search='';if(route()[0]!=='offers')go('offers');else render();break;
 case'offer-guide':showModal('探すの使い方',`<ol class="steps"><li><b>気になる案件を選ぶ</b><span>獲得条件と期限を確認しましょう。</span></li><li><b>「チャレンジする」からサービスを利用</b><span>外部ブラウザでサービスのページを開きます。エントリーが必要な案件は先にエントリーします。</span></li><li><b>マイ案件で成果ステータスを確認</b><span>承認されると付与予定に登録され、審査後に交換可能になります。</span></li></ol>${button('案件を探す','close','btn primary wide')}`);break;
 case'challenge-guide':showModal('チャレンジボーナスのしくみ',`<p>期間内に対象案件の参加人数が目標に達すると、参加者全員に通常報酬とは別のボーナスが付与されるキャンペーンです。</p><ol class="steps"><li><b>対象案件にチャレンジ</b><span>エントリーが必要な案件は先にエントリー。</span></li><li><b>みんなで目標人数を達成</b><span>達成後にチャレンジした方も対象です。</span></li><li><b>承認後にボーナスを付与予定に登録</b><span>通常報酬が否認の場合は対象外です。</span></li></ol><p class="tiny">目標未達の場合はボーナスなし。※現行仕様にない新機能の提案です。</p>${link('開催中のチャレンジを見る','challenges','btn primary wide')}`);break;
 case'slide':carousel=+el.dataset.index;render();break;
 case'category':category=el.dataset.value;render();break;
 case'survey-filter':surveyFilter=el.dataset.value;render();break;
 // --- アンケート ---
 case'begin-survey':answerDraft.step=0;if(!state.surveyStarts.includes(id))state.surveyStarts.push(id);save();render();break;
 case'answer':{const value=+el.dataset.value;answerDraft.answers[answerDraft.step]=value;render();document.querySelector(`[data-action="answer"][data-value="${value}"]`)?.focus({preventScroll:true});break;}
 case'previous-question':answerDraft.step--;render();break;
 case'next-question':{const q=surveys.find(x=>x.id===answerDraft.id);if(answerDraft.answers[answerDraft.step]===undefined)break;if(answerDraft.step<q.questions.length-1){answerDraft.step++;render();}else{showModal('回答を送信しています',`<div class="loading-state"><div class="spinner"></div><p>回答完了の通知を待っています…</p></div>`);modal.querySelector('[data-action="close"]').disabled=true;await wait(1100);if(state.scenario==='error'){showModal('送信できませんでした',`<p>回答内容は保持されています。もう一度お試しください。</p>${button('再送信する','retry-submit','btn primary wide')}`);}else{completeSurvey(state,q.id);save();close();go(`complete/${q.id}`);}}break;}
 case'retry-submit':state.scenario='normal';close();save();document.querySelector('[data-action="next-question"]')?.click();break;
 case'interrupt':showModal('回答を中断しますか？',`<p>このタブを開いている間は、途中から再開できます。</p>${button('アンケート一覧へ戻る','confirm-interrupt','btn secondary wide')}${button('回答を続ける','close','btn primary wide')}`);break;
 case'confirm-interrupt':close();go('surveys');break;
 case'retry':state.scenario='normal';updated('再読み込みしました。');break;
 case'profile':showModal('あなたに合う調査を届けます',`<p>プロフィール（属性情報）が登録されると、対象のアンケートをご案内しやすくなります。</p><div class="info-box">モックでは架空のプロフィールを使用します。初回登録の報酬は現行仕様にない新機能の提案です（${yen(1000)}円相当・仮値）。</div><ul class="profile-fields"><li>年代 <b>30代（サンプル）</b></li><li>居住地域 <b>関東（サンプル）</b></li><li>世帯 <b>2人（サンプル）</b></li><li>性別 <b>回答しない（サンプル）</b></li></ul>${button(state.user.profile?'登録済み':'サンプルで登録を試す','save-profile','btn primary wide',state.user.profile?'disabled':'')}`);break;
 case'save-profile':if(!state.user.profile){state.user.profile=true;schedule(state,'アンケートで獲得',1000,'SURVEY','auto','初回プロフィール登録（モニタ情報取得）');close();save();render();earnedDialog(1000,'プロフィール登録');}break;
 // --- マイページ・ポイント ---
 case'balance':showModal('ポイントの内訳',`<div class="balance-lines"><div><span>合算ポイント</span>${money(total(state),'m-row')}</div><div><span>交換可能（保有）</span>${money(state.user.approved,'m-row')}</div><div><span>準備中（付与予定）</span>${money(state.user.pending,'m-row')}</div><div><span>累計（総獲得）</span>${money(state.user.earned,'m-row')}</div></div><p>準備中のポイントは、ポイント自動判定または審査で確定すると交換可能に移ります。交換できるのは交換可能のポイントだけです。</p>${note}`);break;
 case'exchange':{const c=exchangeConditions(state);showModal('ドットマネーに交換',`<div class="balance-lines"><div><span>交換可能</span>${money(state.user.approved,'m-row')}</div><div><span>最低交換 / 交換単位</span><b>${pt(L(state).minAmount)}pt / ${pt(L(state).unit)}pt</b></div></div><ul class="cond-list"><li class="${c.member?'ok':''}">${icon(c.member?'check':'clock')}Ameba 連携済み</li><li class="${c.sms?'ok':''}">${icon(c.sms?'check':'clock')}SMS 本人確認（交換時に判定）</li><li class="${c.account?'ok':''}">${icon(c.account?'check':'clock')}ドットマネー口座が有効</li><li class="${c.dailyCapOpen?'ok':''}">${icon(c.dailyCapOpen?'check':'clock')}本日の交換総額上限（サービス全体）に余裕がある</li></ul><p class="tiny">交換手数料は無料。入金の反映は最大10分程度。交換手続き画面は次の制作範囲です。${c.sms?'':'SMS 未確認の場合は電話番号登録・認証コード入力へ進みます。'}</p>${button('閉じる','close','btn primary wide')}`);break;}
 case'dotmoney':toast('ドットマネー通帳（https://d-money.jp/history）をアプリ内ブラウザで開きます（デモ）。');break;
 case'guest-help':showModal('ゲストユーザーについて',`<p>ゲストのままでもポイントをためられますが、ドットマネーへの交換には Ameba 会員登録（連携）が必要です。</p>${button('閉じる','close','btn primary wide')}`);break;
 case'guest-signup':showModal('会員登録・ログイン',`<p>Ameba の会員登録・ログインを開き、完了後にゲストのポイントを引き継ぎます（デモでは継続利用者に切り替えます）。</p>${button('会員登録を完了（デモ）','guest-promote','btn primary wide')}`);break;
 case'guest-promote':state.persona='regular';close();updated('ログインしました。ドットマネー口座が反映されました。');break;
 case'help':case'contact':toast(a==='help'?'ヘルプページをアプリ内ブラウザで開きます（デモ）。':'端末のメールアプリを起動します（デモ）。');break;
 case'savings':showModal('交換手数料無料',`<div class="reward-dialog">${mascot('dialog-mascot')}<h3>ドットマネーへの交換で、<br>手数料はかかりません。</h3><p>交換単位 ${pt(L(state).unit)}pt = 1 マネー。最低交換ポイントは ${pt(L(state).minAmount)}pt です。</p><p class="tiny">確定したポイントには有効期限（確定から N ヶ月後の月末。N は運用設定）があります。</p></div>${note}`);break;
 case'notifications':{const items=visibleSlots(state).filter(x=>x.notification&&x.notificationDate<=state.date);showModal('お知らせ',items.length?items.map(x=>`<a class="notification-row" href="#offer/${x.destination}" data-action="notification-link"><span class="meta">${x.notificationDate.replaceAll('-','/')}</span><b>${esc(x.name)}</b><p>${esc(x.notification)}</p>${icon('arrow')}</a>`).join(''):empty('新しいお知らせはありません','キャンペーンの情報をこちらでお届けします。','bell'));break;}
 case'notification-link':close();break;
 case'report':{const today=state.user.history.filter(x=>x.date===state.date&&x.amount>0);const total_=today.reduce((s,x)=>s+x.amount,0);showModal('今日の実績',`<div class="share-card"><div class="share-top"><span class="wordmark">${coin()}タメルコ</span><span>${state.date.replaceAll('-','.')}</span></div><h3>今日も、ひとつずつ。</h3>${money(total_,'m-balance')}<p>${today.length}件のお仕事（確定・準備中を含む）</p>${mascot('share-mascot')}<small>※円相当は交換・換金後の概算値です。</small></div>${button(`${icon('download')}実績カードを保存`,'download-report','btn primary wide')}<p class="tiny">画像（SVG）として保存します。実績レポート画面（月別集計・履歴）は次の制作範囲です。</p>`);break;}
 case'download-report':{const rows=state.user.history.filter(x=>x.date===state.date&&x.amount>0),total_=rows.reduce((s,x)=>s+x.amount,0);download(`tameruko-${state.date}.svg`,`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="800"><rect width="800" height="800" rx="40" fill="#e8f6f0"/><g fill="#12806b" font-family="sans-serif"><text x="64" y="110" font-size="40" font-weight="bold">タメルコ</text><text x="64" y="190" font-size="24">${state.date}</text><text x="64" y="300" font-size="48">今日も、ひとつずつ。</text><text x="64" y="440" font-size="96" font-weight="bold">${yen(total_)}</text><text x="64" y="505" font-size="28">円相当のお小遣い</text><text x="64" y="600" font-size="30">${rows.length}件のお仕事</text><text x="64" y="714" font-size="18">※円相当は交換・換金後の概算値です。デモ実績。</text></g></svg>`,'image/svg+xml');toast('実績カードを保存しました。');break;}
 // --- ポップアップ ---
 case'show-popup':{const pid=document.querySelector('#demo-popup-slot')?.value;const slot=popupSlots(state).find(x=>x.id===pid)||popupSlots(state)[0];if(!slot){toast('表示できるポップアップ枠がありません。');break;}close();await wait(60);showPopup(slot,{markSeen:false});break;}
 case'reset-popup':state.user.daily[state.date]={...day(state),popupSeen:false};updated('本日のポップアップ表示済みをリセットしました。');break;
 case'popup-go':record(state,el.dataset.slot,'tap');close();break;
 // --- デモ操作 ---
 case'auto-review':{const n=autoReview(state);updated(n?`ポイント自動判定を実行し、${n}件を交換可能にしました。`:'自動判定の対象（準備中）はありません。');break;}
 case'manual-review':{const n=manualReview(state);updated(n?`有人審査で${n}件を承認し、交換可能にしました。`:'審査待ちの案件ポイントはありません。');break;}
 case'add-steps':addSteps(state,1000);updated(`歩数を${day(state).steps.toLocaleString()}歩にしました。`);break;
 case'limit-video':state.user.daily[state.date]={...day(state),video:L(state).videoLimit};updated('本日の動画上限に切り替えました。');break;
 case'progress-demo':{const c=[...state.user.cases].reverse().find(x=>['challenging','judging'].includes(x.status));if(!c){toast('承認できる成果がありません。先に案件にチャレンジしてください。');break;}progressOffer(state,c.offerId);updated(`「${c.name}」の成果を承認しました。付与予定（審査）に登録されます。`);break;}
 case'reject-demo':{const c=[...state.user.cases].reverse().find(x=>['challenging','judging'].includes(x.status));if(!c){toast('否認できる成果がありません。');break;}rejectOffer(state,c.offerId);updated(`「${c.name}」の成果を否認しました。`);break;}
 case'advance-challenge':{const paid=advanceChallenges(state,500);updated(paid?`参加人数を更新し、達成分のボーナスを${paid}件登録しました。`:'チャレンジの参加人数を+500人にしました。');break;}
 case'achieve-challenge':{const paid=achieveChallenges(state);updated(paid?`すべてのチャレンジを達成にし、承認済み案件のボーナスを${paid}件登録しました。`:'すべてのチャレンジを達成にしました。成果の承認後にボーナスが登録されます。');break;}
 case'demo':showModal('モックの検証設定',demoPanel());break;
 case'reset':showModal('デモデータを初期化',`<p>このモック内の回答・残高・エントリー・成果を初期状態へ戻します。</p>${button('初期化する','confirm-reset','btn primary wide')}`);break;
 case'confirm-reset':state=initialState();answerDraft=null;viewState='normal';caseTab='challenging';category='すべて';search='';carousel=0;close();updated('初期状態に戻しました。');go('home');setTimeout(()=>showPopup(launchPopup(state)),400);break;
 case'close':close();break;
 }
});
document.addEventListener('change',e=>{const t=e.target;switch(t.id){case'demo-view':viewState=t.value;break;case'demo-date':if(t.value)state.date=t.value;break;case'demo-persona':state.persona=t.value;if(t.value==='new')state.user.installUnlocked=false;if(t.value==='regular')state.user.installUnlocked=true;break;case'demo-steplink':state.stepLink=t.value;break;case'demo-scenario':state.scenario=t.value;break;case'demo-sms':state.user.sms=t.checked;break;case'demo-install':state.user.installUnlocked=t.checked;break;case'demo-boost':state.slots.find(x=>x.id==='autumn').enabled=t.checked;break;case'demo-popup':state.popupMode=t.value;break;case'demo-popup-slot':return;default:return;}updated('確認条件を切り替えました。');});
document.addEventListener('toggle',e=>{if(e.target.id==='mission-more')missionMoreOpen=e.target.open;},true);
document.addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();search=new FormData(e.target).get('search').trim();render();}});
modal.addEventListener('close',()=>{modal.dataset.videoToken='';});
modal.addEventListener('click',e=>{if(e.target.closest('a[href^="#"]'))close();else if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
window.addEventListener('hashchange',()=>{render();document.querySelector('.phone-scroll').scrollTop=0;});
window.addEventListener('storage',e=>{if(e.key===KEY){state=JSON.parse(e.newValue)||initialState();render();}});
save();render();
// 起動時ポップアップ（ホーム表示時のみ・1日1回が既定）
if(route()[0]==='home')setTimeout(()=>showPopup(launchPopup(state)),350);

// タッチとマウスの横スワイプ。縦スクロールと案件カルーセルは維持する。
let homePointer=null, suppressHomeClick=false;
document.addEventListener('pointerdown',e=>{homePointer=null;suppressHomeClick=false;if(!e.isPrimary||e.button!==0||!e.target.closest('.home-panel')||e.target.closest('.hscroll,.chat-room,input,button'))return;homePointer={id:e.pointerId,x:e.clientX,y:e.clientY};});
document.addEventListener('pointerup',e=>{if(!homePointer||homePointer.id!==e.pointerId)return;const dx=e.clientX-homePointer.x,dy=e.clientY-homePointer.y;homePointer=null;if(route()[0]!=='home'||Math.abs(dx)<55||Math.abs(dx)<Math.abs(dy)*1.5)return;suppressHomeClick=true;const i=Math.max(0,HT().findIndex(([k])=>k===route()[1]));const next=i+(dx<0?1:-1);if(HT()[next])go('home/'+HT()[next][0]);setTimeout(()=>{suppressHomeClick=false;},0);});
document.addEventListener('pointercancel',()=>{homePointer=null;});
document.addEventListener('dragstart',e=>{if(e.target.closest('.home-panel')&&!e.target.closest('.hscroll'))e.preventDefault();});
document.addEventListener('click',e=>{if(suppressHomeClick){e.preventDefault();e.stopImmediatePropagation();suppressHomeClick=false;}},true);
document.addEventListener('keydown',e=>{const tab=e.target.closest('.home-tabs [role="tab"]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=HT().findIndex(([k])=>k===tab.dataset.value);const next=e.key==='Home'?0:e.key==='End'?HT().length-1:(i+(e.key==='ArrowRight'?1:-1)+HT().length)%HT().length;go('home/'+HT()[next][0]);setTimeout(()=>document.querySelector('#tab-'+HT()[next][0])?.focus({preventScroll:true}),50);});
